message.content:
{
  "candidate_edge_types": [
    {
      "name": "ESTIMATES_FUTURE_MILESTONE_FROM_PROGRESS_OBSERVATION",
      "definition": "An agent uses an observed progress metric from an ongoing execution, such as a current iteration count and timestamp, to forecast when a future milestone or the overall process will complete.",
      "source_description": "An observation of current progress in an ongoing execution.",
      "target_description": "A temporal estimate or forecast about a future execution milestone or completion time."
    },
    {
      "name": "CONTINUES_MONITORING_WHILE_EXECUTION_INCOMPLETE",
      "definition": "An agent decides to perform another monitoring action because the observed execution has not yet reached a defined completion or terminal state.",
      "source_description": "An observation or state indicating that an ongoing execution is incomplete.",
      "target_description": "A subsequent monitoring action or plan intended to continue checking the ongoing execution."
    },
    {
      "name": "REUSES_PRIOR_OBSERVATION_AS_CURRENT_STATE",
      "definition": "When a new monitoring action produces no new output, an agent adopts the most recent meaningful observation as the current execution state for reasoning and decision-making.",
      "source_description": "A prior observation containing the latest known progress or state of an ongoing execution.",
      "target_description": "An agent reasoning or decision event that adopts that prior observation as the current state."
    },
    {
      "name": "MONITORING_ACTION_YIELDS_UNCHANGED_OBSERVATION",
      "definition": "A monitoring action performed to check the status of an ongoing execution returns an observation identical to the previous known state, indicating that no new progress has occurred.",
      "source_description": "An agent action that polls or checks the status of an ongoing execution.",
      "target_description": "An observation whose content matches the previous known state, indicating no state change."
    },
    {
      "name": "ASSESSES_EXECUTION_HEALTH_FROM_PROGRESS_METRIC",
      "definition": "An agent interprets an observed progress metric from an ongoing execution as an indicator that the execution is proceeding as intended.",
      "source_description": "An observation of a progress metric from an ongoing execution.",
      "target_description": "An evaluative judgment that the execution is healthy or progressing well."
    }
  ]
}

